const C=window.IA_CONTENT||{faq:[],legal:{}};const SLUG=q=>{let t=q.toLowerCase().replace(/ä/g,'ae').replace(/ö/g,'oe').replace(/ü/g,'ue').replace(/ß/g,'ss').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');if(t.length>70){t=t.slice(0,70);t=t.slice(0,t.lastIndexOf('-')>30?t.lastIndexOf('-'):70)}return t};const LNK=t=>esc(t).replace(/https:\/\/[^\s<]*[^\s<.,;)]/g,u=>`<a class="ck-link" href="${u}" target="_blank" rel="noopener noreferrer">${u.replace(/^https:\/\/(www\.)?/,'')}</a>`);const esc=t=>String(t).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));const PHASES=[['1','Orientieren & Leistbarkeit','Budget, Eigenkapital, Bonität – was kann ich mir leisten?',x=>['Geld & Vermögen','Orientierung & Leistbarkeit'].includes(x.cat)],['2','Objektprüfung & Kennzahlen','Kaufpreisfaktor, Rendite, Hausgeld – rechnet sich das Objekt?',x=>x.cat==='Objektauswahl & Kaufentscheidung'||(x.cat==='Kapitalanlage & Vermögensaufbau'&&!/AfA|15-%|steuerfrei|nach Steuern/.test(x.q))],['3','Steuern & Cashflow','AfA, Werbungskosten, Sanierungsaufwand, Mieteinnahmen absichern',x=>['Steuern & Werbungskosten','Vermieten & Absicherung'].includes(x.cat)||(x.cat==='Kapitalanlage & Vermögensaufbau'&&/AfA|15-%|steuerfrei|nach Steuern/.test(x.q))],['4','Bankgespräch & Kreditmappe','Zinsbindung, Unterlagen, Kreditmappe – sicher ins Bankgespräch',x=>x.cat==='Finanzierung & Bankenpraxis']];const phaseOf=x=>{const h=PHASES.find(P=>P[3](x));return h?h[0]:'0'};
const faqItem=(x,i)=>`<article data-search="${esc((x.q+' '+x.cat+' '+x.l1+' '+x.l2).toLowerCase())}"><button class="route-q"><span>${i+1}</span><strong>${esc(x.q)}</strong><b>+</b></button><div class="route-a" hidden><div class="callout"><strong>Ich brauche Orientierung</strong><p>${esc(x.l1)}</p></div><div class="next"><strong>Nächster Schritt:</strong> ${esc(x.next)}</div><details class="level2"><summary>Ich möchte alle Details wissen</summary><p>${esc(x.l2)}</p></details><p><a class="ck-link" href="/wissen/${SLUG(x.q)}">Antwort als eigene Seite öffnen und teilen</a></p><p class="faq-disclaimer">${esc(C.disclaimer||'')}</p></div></article>`;const faq=[...PHASES.map(P=>[P[0],P[1],P[2]]),['0','Rund um ImmoAdv und Ihre Eingaben','Datenschutz, Preise und was in welches Feld gehört']].map(([n,t,d])=>{const L=C.faq.map((x,i)=>[x,i]).filter(([x])=>phaseOf(x)===n);return L.length?`<section class="wp-sec" id="phase-${n}" data-phase="${n}"><h2 class="wp-h">${n!=='0'?`<b>Phase ${n}</b> `:''}${esc(t)}</h2><p class="form-note">${esc(d)}</p><div class="route-accordion">${L.map(([x,i])=>faqItem(x,i)).join('')}</div></section>`:''}).join('');const phaseNav=`<nav class="wp-nav" aria-label="Wissen in vier Phasen">${PHASES.map(P=>`<a href="#phase-${P[0]}"><b>${P[0]}</b><strong>${esc(P[1])}</strong><span>${esc(P[2])}</span><em>${C.faq.filter(x=>phaseOf(x)===P[0]).length} Antworten</em></a>`).join('')}</nav>`;
